fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    let mut eligible_count: u8 = 0;
    let mut i: usize = 0;
    let limit = std::cmp::min(n as usize, participations.len());
    
    while i < limit {
        let attendance = participations[i];
        let remaining_sessions = 5 - attendance;
        
        if remaining_sessions >= k {
            eligible_count += 1;
        }
        
        i += 1;
    }
    
    eligible_count / 3
}